import{_ as e,o as i,c as r,ag as l}from"./chunks/framework.D9ghT4bC.js";const d=JSON.parse('{"title":"用户协议","description":"","frontmatter":{},"headers":[],"relativePath":"zh/Terms-of-Service.md","filePath":"zh/Terms-of-Service.md"}'),t={name:"zh/Terms-of-Service.md"};function o(n,a,s,h,c,u){return i(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="用户协议" tabindex="-1">用户协议 <a class="header-anchor" href="#用户协议" aria-label="Permalink to &quot;用户协议&quot;">​</a></h1><p>本协议适用于 UncivCN 社区提供的服务：社区联机服务器、社区下载服务器与本文档站。这些服务由社区维护者以个人身份自建、自维护，免费且非商业。它们<strong>不是官方服务</strong>：Unciv 游戏由上游团队（<a href="https://github.com/yairm210/Unciv" target="_blank" rel="noreferrer">https://github.com/yairm210/Unciv</a>）开发，上游团队没有参与、也不对这些服务负责。使用任一服务即表示你同意本协议与<a href="/Unciv/zh/Privacy-Policy.html">隐私政策</a>。</p><h2 id="_1-服务内容" tabindex="-1">1. 服务内容 <a class="header-anchor" href="#_1-服务内容" aria-label="Permalink to &quot;1. 服务内容&quot;">​</a></h2><ul><li><strong>联机服务器</strong>：存档上传与下载、同步回合，以及可选的游戏内聊天。</li><li><strong>下载服务器</strong>：提供 UncivCN 的版本清单与下载直链（安装包本身托管在 GitHub Release 上）。</li><li><strong>文档站</strong>：项目文档与更新日志。</li></ul><p>以上都是免费的技术设施，不销售任何付费内容、订阅或游戏道具。</p><h2 id="_2-账号" tabindex="-1">2. 账号 <a class="header-anchor" href="#_2-账号" aria-label="Permalink to &quot;2. 账号&quot;">​</a></h2><ul><li>玩家 ID 由游戏客户端生成。请妥善保管密码，不要与其他网站使用相同的密码。</li><li>服务器可能采用审核制注册：新账号需经管理员确认后才能使用联机功能。</li><li>请勿共享、转借或出售账号；账号下的一切行为视为账号持有人所为。</li><li>如怀疑账号被盗用，请及时联系我们。</li></ul><h2 id="_3-使用规范" tabindex="-1">3. 使用规范 <a class="header-anchor" href="#_3-使用规范" aria-label="Permalink to &quot;3. 使用规范&quot;">​</a></h2><p>禁止：</p><ul><li>发布或上传违法违规、仇恨、骚扰内容（包括聊天消息与存档文件内的文本）；</li><li>上传他人存档、外挂或恶意数据；</li><li>对服务器进行攻击、扫描、爬虫、超量请求，或绕过限流；</li><li>利用本服务从事商业经营；</li><li>冒充维护者、上游项目或其他玩家。</li></ul><p>视情节，我们可能警告、删除数据、封禁账号，严重时向执法机关报告。</p><h2 id="_4-存档与数据" tabindex="-1">4. 存档与数据 <a class="header-anchor" href="#_4-存档与数据" aria-label="Permalink to &quot;4. 存档与数据&quot;">​</a></h2><ul><li>联机服务器上的存档用于在玩家之间传递回合，请始终保留自己的本地备份。</li><li>因法律合规要求、不可抗力、硬件故障或服务调整，我们可能暂停服务或清空数据。我们会尽可能提前在社区公告并提供存档导出通道，但不对数据丢失承担赔偿责任。</li><li>服务变更或关停时，请通过 QQ 群或 GitHub Issues 联系我们导出存档。</li></ul><h2 id="_5-免责声明" tabindex="-1">5. 免责声明 <a class="header-anchor" href="#_5-免责声明" aria-label="Permalink to &quot;5. 免责声明&quot;">​</a></h2><p>服务按「现状」提供，不保证可用性、连续性与数据完整性。玩家之间的纠纷（包括游戏内的行为）与我们无关。我们不对间接损失负责；适用法律不允许限制的责任不受本条影响。</p><h2 id="_6-变更与终止" tabindex="-1">6. 变更与终止 <a class="header-anchor" href="#_6-变更与终止" aria-label="Permalink to &quot;6. 变更与终止&quot;">​</a></h2><ul><li>我们可能随时调整、暂停或终止部分或全部服务，尤其是为满足法律合规要求时。</li><li>本协议可能更新，更新会在文档站与更新日志中说明；继续使用即视为接受更新后的条款。</li><li>本协议适用服务器部署地的法律；发生争议时我们先通过沟通解决。</li></ul><p>联系方式：<a href="https://qm.qq.com/q/j92c3iUnZ0" target="_blank" rel="noreferrer">QQ 群</a> 或 <a href="https://github.com/AutumnPizazz/Unciv/issues" target="_blank" rel="noreferrer">GitHub Issues</a>。</p>',18)])])}const m=e(t,[["render",o]]);export{d as __pageData,m as default};
